const articles = $('Sheets — Articles récents').all().map(i => i.json).filter(a => a.Status === 'produit_draft' || a.Status === 'publié').slice(-5);
const courses = $('Sheets — Cours récents').all().map(i => i.json).filter(c => c.Status !== 'nouveau').slice(-3);

return [{ json: { recent_articles: articles, recent_courses: courses } }];

const response = $input.first().json;

let newsletter;
try {
  const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  newsletter = JSON.parse(text);
} catch (e) {
  throw new Error('Erreur parsing newsletter: ' + e.message);
}

return [{
  json: {
    subject: newsletter.subject || 'Newsletter Max-Morrys',
    preview_text: newsletter.preview_text || '',
    html_body: newsletter.html_body || '',
    plain_text: newsletter.plain_text || '',
    main_cta: newsletter.main_cta || {},
    generated_at: new Date().toISOString(),
    status: 'draft'
  }
}];
